// Original generated four-frame sheet; see art/MOVE-PROVENANCE.md.
// The bright core is the projectile anchor. Individual offsets prevent generated frame padding from making it jump.
const CORES = [[0.729, 0.572], [0.653, 0.579], [0.720, 0.487], [0.653, 0.487]];
let fireball = null;

/** Draw one loop frame at the projectile's actual centre; return false while unavailable so procedural art can remain. */
export function drawFireSprite(ctx, x, y, angle, size, time) {
  if (typeof Image === "undefined") return false;
  if (!fireball) { fireball = new Image(); fireball.src = FIREBALL; }
  if (!fireball.complete || !fireball.naturalWidth) return false;
  const frame = Math.floor(Math.max(0, time) * 12) % 4;
  const w = fireball.naturalWidth / 2, h = fireball.naturalHeight / 2;
  const height = size * h / w;
  const [ax, ay] = CORES[frame];
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(fireball, frame % 2 * w, Math.floor(frame / 2) * h, w, h, -ax * size, -ay * height, size, height);
  ctx.restore();
  return true;
}
const FIREBALL = "data:image/webp;base64,";
